<?php require 'header.php'; $db=db_load(); $page_title='Appointments'; ?><div class="admin-top"><h1>Appointments</h1><a class="btn" href="calendar.php">Open Calendar</a></div><div class="table-wrap"><table><tr><th>Appointment No</th><th>Patient No</th><th>Patient</th><th>Date</th><th>Time</th><th>Status</th><th>Amount</th><th>Action</th></tr><?php foreach(array_reverse($db['appointments']) as $a): $p=find_item($db['patients'],$a['patient_id']); ?><tr><td><?=e($a['number'])?></td><td><?=e($p['number']??'-')?></td><td><?=e($p['name']??'-')?></td><td><?=e(date_fmt($a['date']))?></td><td><?=e($a['time'])?></td><td><span class="badge"><?=e($a['status'])?></span></td><td>₹<?=number_format((float)$a['amount'],2)?></td><td><a class="btn btn-sm" href="appointment-edit.php?id=<?=e($a['id'])?>">Open</a></td></tr><?php endforeach; ?></table></div><?php require 'footer.php'; ?>
